  const renderers = {overview, 'storm-intelligence':stormIntelligence, initiation, forecasts, fusion, ravi, replay, 'atmospheric-intelligence':atmosphere, analytics, provenance, reports, settings};
  function routeKey(){const p=decodeURIComponent(location.pathname).replace(/\/$/,''); if(!p||p==='/overview')return'overview';return p.slice(1);}
  function render(){let key=routeKey();if(key==='live-nowcast'){location.replace('/live-nowcast');return;}if(!renderers[key])key='overview';document.title=`DEVLOK / VAYU — ${labels[key]}`;document.getElementById('crumbCurrent').textContent=labels[key];document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===key);if(a.dataset.route===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const container=document.getElementById('pageContent');container.innerHTML=renderers[key]();container.classList.remove('fade-in');void container.offsetWidth;container.classList.add('fade-in');bindPage(key);}
