  function answerQuery(q){const text=q.toLowerCase();let response;if(/intensif|strong|storm-042/.test(text)){response='<b>STORM-042</b> is the fixture object marked intensifying. Its displayed reflectivity proxy rises from 36 to 48 dBZ across five replay steps; this is simulated evidence, not a live observation.';}else if(/initiat|new storm|born|develop/.test(text)){response='<b>INIT-018</b> is the separate initiation candidate east of Ranchi. Its 0.64 scenario score is not calibrated; satellite, environment, and radar precursor fields are simulated placeholders.';}else if(/insufficient|missing|data/.test(text)){response='<b>Observed lightning is unavailable.</b> Radar, satellite thermal proxy, and environment fields are simulated. Missing input is not a clear-hazard signal.';}else if(/why|evidence|confidence|reliab/.test(text)){response='<b>STORM-042 is WATCH / medium illustrative reliability.</b> The fixture shows rising reflectivity proxy and persistent centroid motion. No measured confidence calibration or live precursor analysis exists.';}else if(/patna|arrival|affect/.test(text)){response='<b>No validated arrival forecast is available.</b> The demo track is a centroid-motion scenario around Ranchi; it does not support a reliable impact or ETA claim for Patna.';}else{response='I can answer only from the current storm-object fixture. Try asking about intensifying storms, INIT-018, evidence for STORM-042, or unavailable inputs.';}return `${response}<span class="answer-meta">STRUCTURED FIXTURE RESPONSE · ${scenario.cycle}</span>`;}
  function bindOverviewHero(){
    const track=document.querySelector('.vayu-hero-track');
    if(!track)return;
    const media=window.matchMedia('(prefers-reduced-motion: reduce)');
    const beats=[...track.querySelectorAll('[data-beat]')];
    const indicators=[...track.querySelectorAll('.hero-beat-count i')];
    const stage=track.querySelector('.hero-stage-label');
    let frame=0,current=-1,reducedMode=media.matches;
    const missionGrid=document.querySelector('.mission-grid');
    if(missionGrid){
      missionGrid.querySelectorAll('.mission-card').forEach((card,index)=>card.style.setProperty('--mission-index',String(index)));
      missionGrid.classList.add('mission-grid-reveal');
    }
    const names=['ATMOSPHERIC SCENARIO','STORM-042 · OBJECT FOCUS','MISSION SELECTOR'];
    const setBeat=index=>{
      if(index===current&&reducedMode===media.matches)return;
      current=index;
      reducedMode=media.matches;
      track.dataset.heroBeat=String(index);
      beats.forEach((beat,i)=>{
        const active=i===index;
        beat.classList.toggle('is-active',active);
        const visible=active||media.matches;
        beat.setAttribute('aria-hidden',String(!visible));
        if(visible)beat.removeAttribute('inert');else beat.setAttribute('inert','');
      });
      indicators.forEach((dot,i)=>dot.classList.toggle('active',i===index));
      if(stage)stage.innerHTML=`0${index+1} <i>/</i> ${names[index]}`;
    };
    const update=()=>{
      frame=0;
      if(missionGrid&&!missionGrid.classList.contains('is-visible')&&missionGrid.getBoundingClientRect().top<innerHeight*.9)missionGrid.classList.add('is-visible');
      if(media.matches||!track.classList.contains('scroll-story-active'))return;
      const range=Math.max(1,track.offsetHeight-track.querySelector('.vayu-hero-sticky').offsetHeight);
      const progress=Math.min(1,Math.max(0,-track.getBoundingClientRect().top/range));
      setBeat(progress<.31?0:progress<.62?1:2);
    };
    const schedule=()=>{if(!frame)frame=requestAnimationFrame(update);};
    const configure=()=>{
      track.classList.toggle('scroll-story-active',!media.matches);
      setBeat(0);
      schedule();
    };
    window.addEventListener('scroll',schedule,{passive:true});
    window.addEventListener('resize',schedule,{passive:true});
    if(media.addEventListener)media.addEventListener('change',configure);else media.addListener(configure);
    configure();
  }
