    document.querySelectorAll('[data-decision]').forEach(b=>b.addEventListener('click',()=>{const decision={object:b.dataset.object,value:b.dataset.decision,at:new Date().toISOString()};const rows=JSON.parse(localStorage.getItem('vayu-triage-log')||'[]');rows.push(decision);localStorage.setItem('vayu-triage-log',JSON.stringify(rows));document.getElementById('decisionFeedback').textContent=`${decision.object} marked ${decision.value}. Saved in this browser only; human review remains responsible for action.`;const prov=document.getElementById('provenanceDecision');if(prov)prov.textContent=`${decision.object} · ${decision.value}`;}));
